@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IAsyncDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<h4 class="text-muted">@WarehouseState.SelectedWarehouseName</h4>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text display-4">
                    @if (AlertService.LowStockCount > 0)
                    {
                        <span class="text-danger">@AlertService.LowStockCount</span>
                    }
                    else
                    {
                        <span class="text-success">0</span>
                    }
                </p>
                <p class="text-muted">
                    Items below minimum stock level
                    @if (_isPolling)
                    {
                        <span class="spinner-border spinner-border-sm ms-2" role="status"></span>
                    }
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _isPolling;
    private Action? _warehouseChangeHandler;
    private Action? _alertChangeHandler;

    protected override void OnInitialized()
    {
        _warehouseChangeHandler = () => InvokeAsync(async () =>
        {
            await AlertService.RefreshAlertCountAsync();
            StateHasChanged();
        });
        WarehouseState.OnChange += _warehouseChangeHandler;

        _alertChangeHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertChangeHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await StartPollingAsync();
        }
    }

    private async Task StartPollingAsync()
    {
        _isPolling = true;
        _cts = new CancellationTokenSource();

        // Initial fetch
        await AlertService.RefreshAlertCountAsync();
        StateHasChanged();

        // Poll every 10 seconds
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(_cts.Token))
            {
                await AlertService.RefreshAlertCountAsync();
                await InvokeAsync(StateHasChanged);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose
        }
        finally
        {
            _isPolling = false;
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_warehouseChangeHandler is not null)
            WarehouseState.OnChange -= _warehouseChangeHandler;

        if (_alertChangeHandler is not null)
            AlertService.OnAlertCountChanged -= _alertChangeHandler;

        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

